import React, { useState, useEffect } from "react";
import "./App.css";
import {
  FaFacebookF,
  FaInstagram,
  FaYoutube
} from "react-icons/fa";

const API_URL = "http://localhost:8000";

// ========== FUNCIÓN AUXILIAR PARA MANEJAR ERRORES ==========
const manejarError = (error) => {
  if (error.detail) {
    if (typeof error.detail === "string") {
      return error.detail;
    } else if (Array.isArray(error.detail)) {
      // Errores de validación de FastAPI (422)
      return error.detail.map(err => {
        const campo = err.loc ? err.loc.join('.') : 'campo desconocido';
        return `${campo}: ${err.msg}`;
      }).join('\n');
    }
  }
  if (error.message) return error.message;
  return "Error desconocido";
};

export default function App() {
  const [vista, setVista] = useState("home");
  const [vistaDetalle, setVistaDetalle] = useState(false);
  const [planillaSeleccionada, setPlanillaSeleccionada] = useState(null);

  // --- Empleados ---
  const [empleados, setEmpleados] = useState([]);
  const [nuevoEmpleado, setNuevoEmpleado] = useState({
    nombre: "",
    dui: "",
    area: "",
    puesto: "",
    salario_mensual: 0,
    fecha_ingreso: ""
  });
  const [empleadoCargado, setEmpleadoCargado] = useState(false);
  const [empleadoEditandoId, setEmpleadoEditandoId] = useState(null);
  const [filtroEmpleados, setFiltroEmpleados] = useState("");

  // --- Períodos ---
  const [periodos, setPeriodos] = useState([]);
  const [nuevoPeriodo, setNuevoPeriodo] = useState({
    mes: 1, año: 2026, fecha_corte: "", total_general: 0
  });
  const [periodoCargado, setPeriodoCargado] = useState(false);

  // --- Planillas ---
  const [planillas, setPlanillas] = useState([]);
  const [nuevaPlanilla, setNuevaPlanilla] = useState({
    periodo_id: "",
    empleado_id: "",
    sueldo_base: 0,
    horas_extras_diurnas: 0,
    horas_extras_nocturnas: 0,
    horas_nocturnas: 0,
    subsidio_alimentacion: 0,
    bono_extra: 0,
    aplica_nocturnidad: false,
    quincena25_aplica: false
  });
  const [planillaCargado, setPlanillaCargado] = useState(false);
  const [planillaEditandoId, setPlanillaEditandoId] = useState(null);

  // Cargar datos al iniciar
  useEffect(() => {
    const cargarDatos = async () => {
      try {
        const [resEmp, resPer, resPla] = await Promise.all([
          fetch(`${API_URL}/empleado`),
          fetch(`${API_URL}/periodo`),
          fetch(`${API_URL}/planilla`)
        ]);
        if (resEmp.ok) {
          const data = await resEmp.json();
          setEmpleados(data);
        }
        if (resPer.ok) {
          const data = await resPer.json();
          data.sort((a, b) => new Date(a.fecha_corte) - new Date(b.fecha_corte));
          setPeriodos(data);
        }
        if (resPla.ok) {
          const data = await resPla.json();
          setPlanillas(data);
        }
      } catch (error) {
        console.error("Error cargando datos:", error);
      }
    };
    cargarDatos();
  }, []);

  // --- CRUD Empleados ---
  const crearEmpleado = async (e) => {
    e.preventDefault();
    const duiRegex = /^\d{8}-\d{1}$/;
    if (!duiRegex.test(nuevoEmpleado.dui)) {
      alert("El DUI debe tener el formato ########-# (8 dígitos, guion y 1 dígito)");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/empleado/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados([...empleados, data]);
        limpiarFormularioEmpleado();
        alert("Empleado creado exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al crear empleado:", error);
      alert("Error de conexión con el backend");
    }
  };

  const actualizarEmpleado = async (e) => {
    e.preventDefault();
    const duiRegex = /^\d{8}-\d{1}$/;
    if (!duiRegex.test(nuevoEmpleado.dui)) {
      alert("El DUI debe tener el formato ########-# (8 dígitos, guion y 1 dígito)");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/empleado/${empleadoEditandoId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados(empleados.map(emp => emp.id === data.id ? data : emp));
        limpiarFormularioEmpleado();
        alert("Empleado actualizado exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al actualizar empleado:", error);
      alert("Error de conexión con el backend");
    }
  };

  const eliminarEmpleado = async (id) => {
    if (!window.confirm("¿Seguro que deseas eliminar este empleado?")) return;
    try {
      const res = await fetch(`${API_URL}/empleado/${id}`, { method: "DELETE" });
      if (res.ok) {
        setEmpleados(empleados.filter(emp => emp.id !== id));
        alert("Empleado eliminado");
      } else {
        alert("Error al eliminar, verificar si tiene planillas asociadas");
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
    }
  };

  const cargarEmpleado = (emp) => {
    // Asegurar que todos los campos tengan un valor
    setNuevoEmpleado({
      nombre: emp.nombre || "",
      dui: emp.dui || "",
      area: emp.area || "",
      puesto: emp.puesto || "",
      salario_mensual: emp.salario_mensual || 0,
      fecha_ingreso: emp.fecha_ingreso || ""
    });
    setEmpleadoCargado(true);
    setEmpleadoEditandoId(emp.id);
  };

  const limpiarFormularioEmpleado = () => {
    setNuevoEmpleado({ nombre: "", dui: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: "" });
    setEmpleadoCargado(false);
    setEmpleadoEditandoId(null);
  };

  // --- CRUD Períodos --- (sin cambios)
  const crearPeriodo = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/periodo/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoPeriodo),
      });
      if (res.ok) {
        const data = await res.json();
        const nuevosPeriodos = [...periodos, data];
        nuevosPeriodos.sort((a, b) => new Date(a.fecha_corte) - new Date(b.fecha_corte));
        setPeriodos(nuevosPeriodos);
        limpiarFormularioPeriodo();
        alert("Período creado exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al crear periodo:", error);
      alert("Error de conexión con el backend");
    }
  };

  const eliminarPeriodo = async (id) => {
    if (!window.confirm("¿Seguro que deseas eliminar este período? Si tiene planillas asociadas, no se podrá eliminar.")) return;
    try {
      const res = await fetch(`${API_URL}/periodo/${id}`, { method: "DELETE" });
      if (res.ok) {
        setPeriodos(periodos.filter(per => per.id !== id));
        alert("Período eliminado exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
      alert("Error de conexión con el backend");
    }
  };

  const cargarPeriodo = (per) => {
    setNuevoPeriodo({
      mes: per.mes,
      año: per.año,
      fecha_corte: per.fecha_corte,
      total_general: per.total_general || 0
    });
    setPeriodoCargado(true);
  };

  const limpiarFormularioPeriodo = () => {
    setNuevoPeriodo({ mes: 1, año: 2026, fecha_corte: "", total_general: 0 });
    setPeriodoCargado(false);
  };

  const generarProximoPeriodo = () => {
    if (periodos.length === 0) {
      setNuevoPeriodo({
        mes: 1,
        año: 2026,
        fecha_corte: "2026-01-31",
        total_general: 0
      });
      return;
    }
    const ultimo = periodos.reduce((a, b) => a.fecha_corte > b.fecha_corte ? a : b);
    const fecha = new Date(ultimo.fecha_corte);
    let mes = fecha.getMonth() + 2;
    let año = fecha.getFullYear();
    if (mes > 12) {
      mes = 1;
      año += 1;
    }
    const ultimoDia = new Date(año, mes, 0).getDate();
    const fechaCorte = `${año}-${String(mes).padStart(2, '0')}-${String(ultimoDia).padStart(2, '0')}`;
    setNuevoPeriodo({
      mes: mes,
      año: año,
      fecha_corte: fechaCorte,
      total_general: 0
    });
    setPeriodoCargado(false);
  };

  // --- CRUD Planillas --- (sin cambios, solo añadir manejarError en errores)
  const crearPlanilla = async (e) => {
    e.preventDefault();
    if (!nuevaPlanilla.periodo_id || !nuevaPlanilla.empleado_id) {
      alert("Debes seleccionar un período y un empleado");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/planilla/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          periodo_id: parseInt(nuevaPlanilla.periodo_id),
          empleado_id: parseInt(nuevaPlanilla.empleado_id),
          sueldo_base: nuevaPlanilla.sueldo_base,
          horas_extras_diurnas: nuevaPlanilla.horas_extras_diurnas,
          horas_extras_nocturnas: nuevaPlanilla.horas_extras_nocturnas,
          horas_nocturnas: nuevaPlanilla.horas_nocturnas,
          subsidio_alimentacion: nuevaPlanilla.subsidio_alimentacion,
          bono_extra: nuevaPlanilla.bono_extra,
          aplica_nocturnidad: nuevaPlanilla.aplica_nocturnidad,
          quincena25_aplica: nuevaPlanilla.quincena25_aplica
        }),
      });
      if (res.ok) {
        const data = await res.json();
        setPlanillas([...planillas, data]);
        limpiarFormularioPlanilla();
        alert("Planilla registrada exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al crear planilla:", error);
      alert("Error de conexión con el backend");
    }
  };

  const actualizarPlanilla = async (e) => {
    e.preventDefault();
    if (!nuevaPlanilla.periodo_id || !nuevaPlanilla.empleado_id) {
      alert("Debes seleccionar un período y un empleado");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/planilla/${planillaEditandoId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          periodo_id: parseInt(nuevaPlanilla.periodo_id),
          empleado_id: parseInt(nuevaPlanilla.empleado_id),
          sueldo_base: nuevaPlanilla.sueldo_base,
          horas_extras_diurnas: nuevaPlanilla.horas_extras_diurnas,
          horas_extras_nocturnas: nuevaPlanilla.horas_extras_nocturnas,
          horas_nocturnas: nuevaPlanilla.horas_nocturnas,
          subsidio_alimentacion: nuevaPlanilla.subsidio_alimentacion,
          bono_extra: nuevaPlanilla.bono_extra,
          aplica_nocturnidad: nuevaPlanilla.aplica_nocturnidad,
          quincena25_aplica: nuevaPlanilla.quincena25_aplica
        }),
      });
      if (res.ok) {
        const data = await res.json();
        setPlanillas(planillas.map(p => p.id === data.id ? data : p));
        limpiarFormularioPlanilla();
        alert("Planilla actualizada exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al actualizar planilla:", error);
      alert("Error de conexión con el backend");
    }
  };

  const eliminarPlanilla = async (id) => {
    if (!window.confirm("¿Seguro que deseas eliminar esta planilla?")) return;
    try {
      const res = await fetch(`${API_URL}/planilla/${id}`, { method: "DELETE" });
      if (res.ok) {
        setPlanillas(planillas.filter(p => p.id !== id));
        alert("Planilla eliminada exitosamente");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        alert(`Error:\n${mensaje}`);
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
      alert("Error de conexión con el backend");
    }
  };

  const cargarPlanilla = (pl) => {
    setNuevaPlanilla({
      periodo_id: pl.periodo_id,
      empleado_id: pl.empleado_id,
      sueldo_base: pl.sueldo_base,
      horas_extras_diurnas: pl.horas_extras_diurnas,
      horas_extras_nocturnas: pl.horas_extras_nocturnas,
      horas_nocturnas: pl.horas_nocturnas,
      subsidio_alimentacion: pl.subsidio_alimentacion,
      bono_extra: pl.bono_extra,
      aplica_nocturnidad: pl.aplica_nocturnidad,
      quincena25_aplica: pl.quincena25_aplica
    });
    setPlanillaCargado(true);
    setPlanillaEditandoId(pl.id);
  };

  const limpiarFormularioPlanilla = () => {
    setNuevaPlanilla({
      periodo_id: "",
      empleado_id: "",
      sueldo_base: 0,
      horas_extras_diurnas: 0,
      horas_extras_nocturnas: 0,
      horas_nocturnas: 0,
      subsidio_alimentacion: 0,
      bono_extra: 0,
      aplica_nocturnidad: false,
      quincena25_aplica: false
    });
    setPlanillaCargado(false);
    setPlanillaEditandoId(null);
  };

  const verDetalle = (pl) => {
    setPlanillaSeleccionada(pl);
    setVistaDetalle(true);
  };

  const volverAListado = () => {
    setVistaDetalle(false);
    setPlanillaSeleccionada(null);
  };

  // ========== RENDERIZADO DE PÁGINAS ==========
  // (Las funciones renderHome, renderEmpleados, renderPeriodos, renderPlanillas
  //  son las mismas que ya tenías, solo asegúrate de que el formulario de empleados
  //  use onSubmit={empleadoCargado ? actualizarEmpleado : crearEmpleado})
  // 
  // Para ahorrar espacio, pondré solo la parte del renderEmpleados que es la que cambia.
  // Pero en tu archivo, mantén todas las demás secciones igual.

  const renderEmpleados = () => {
    const empleadosFiltrados = empleados.filter(emp =>
      emp.nombre.toLowerCase().includes(filtroEmpleados.toLowerCase()) ||
      (emp.dui && emp.dui.toLowerCase().includes(filtroEmpleados.toLowerCase()))
    );

    return (
      <>
        <section className="hero" style={{ height: "250px" }}>
          <div className="overlay">
            <h1 style={{ fontSize: "36px" }}>Gestión de Empleados</h1>
          </div>
        </section>
        <div style={{ padding: "40px 20px", background: "#efefef", display: "flex", justifyContent: "center" }}>
          <div style={{ maxWidth: "800px", width: "100%", background: "white", padding: "30px", borderRadius: "8px" }}>
            <h2 style={{ textAlign: "center", color: "#d71920", marginBottom: "20px" }}>
              {empleadoCargado ? "Editar Empleado" : "Agregar Nuevo Empleado"}
            </h2>
            <form onSubmit={empleadoCargado ? actualizarEmpleado : crearEmpleado}>
              <input
                type="text"
                placeholder="Nombre"
                value={nuevoEmpleado.nombre}
                onChange={e => setNuevoEmpleado({...nuevoEmpleado, nombre: e.target.value})}
                required
              />
              <input
                type="text"
                placeholder="DUI (ej: 12345678-9)"
                value={nuevoEmpleado.dui}
                onChange={e => setNuevoEmpleado({...nuevoEmpleado, dui: e.target.value})}
                required
              />
              <input
                type="text"
                placeholder="Área"
                value={nuevoEmpleado.area}
                onChange={e => setNuevoEmpleado({...nuevoEmpleado, area: e.target.value})}
                required
              />
              <input
                type="text"
                placeholder="Puesto"
                value={nuevoEmpleado.puesto}
                onChange={e => setNuevoEmpleado({...nuevoEmpleado, puesto: e.target.value})}
                required
              />
              <input
                type="number"
                step="0.01"
                placeholder="Salario mensual"
                value={nuevoEmpleado.salario_mensual}
                onChange={e => setNuevoEmpleado({...nuevoEmpleado, salario_mensual: parseFloat(e.target.value)})}
                required
              />
              <input
                type="date"
                placeholder="Fecha ingreso"
                value={nuevoEmpleado.fecha_ingreso}
                onChange={e => setNuevoEmpleado({...nuevoEmpleado, fecha_ingreso: e.target.value})}
                required
              />
              <div style={{ display: "flex", gap: "10px" }}>
                <button type="submit" style={{ flex: 1 }}>
                  {empleadoCargado ? "Actualizar Empleado" : "Guardar Empleado"}
                </button>
                {empleadoCargado && (
                  <button type="button" onClick={limpiarFormularioEmpleado} style={{ background: "#666", flex: 1 }}>
                    Cancelar Edición
                  </button>
                )}
              </div>
            </form>
            <hr style={{ margin: "30px 0" }} />

            <div style={{ marginBottom: "20px" }}>
              <input
                type="text"
                placeholder="🔍 Buscar por nombre o DUI..."
                value={filtroEmpleados}
                onChange={e => setFiltroEmpleados(e.target.value)}
                style={{
                  width: "100%",
                  padding: "10px 12px",
                  borderRadius: "8px",
                  border: "1px solid #ddd",
                  fontSize: "15px"
                }}
              />
            </div>

            <h3 style={{ textAlign: "center", marginBottom: "15px" }}>
              Lista de Empleados {empleadosFiltrados.length !== empleados.length && `(${empleadosFiltrados.length} de ${empleados.length})`}
            </h3>
            <ul style={{ listStyle: "none", padding: 0 }}>
              {empleadosFiltrados.map(emp => (
                <li key={emp.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px", borderBottom: "1px solid #eee" }}>
                  <span>
                    <strong>{emp.nombre}</strong> - DUI: {emp.dui} - {emp.puesto} (${emp.salario_mensual})
                  </span>
                  <div style={{ display: "flex", gap: "8px" }}>
                    <button onClick={() => cargarEmpleado(emp)} style={{ background: "#007bff", color: "white", border: "none", padding: "5px 12px", borderRadius: "4px", cursor: "pointer" }}>
                      Cargar
                    </button>
                    <button onClick={() => eliminarEmpleado(emp.id)} style={{ background: "#d71920", color: "white", border: "none", padding: "5px 12px", borderRadius: "4px", cursor: "pointer" }}>
                      Eliminar
                    </button>
                  </div>
                </li>
              ))}
            </ul>
            {empleadosFiltrados.length === 0 && (
              <p style={{ textAlign: "center", color: "#999", marginTop: "20px" }}>
                No se encontraron empleados con ese criterio.
              </p>
            )}
          </div>
        </div>
      </>
    );
  };

  // --- Las funciones renderHome, renderPeriodos, renderPlanillas y renderDetallePlanilla
  // son idénticas a las que ya tenías. No las repito aquí para no alargar,
  // pero asegúrate de que en tu App.js estén incluidas.
  // Si necesitas el código completo con todas, avísame.

  // --- Render principal ---
  return (
    <div className="app">
      <header className="navbar">
        <div className="logo-container">
          <div className="logo-circle">★</div>
          <span className="logo-text">TEXACO</span>
        </div>
        <nav className="nav-links">
          <a href="#" onClick={() => { setVista("home"); limpiarFormularioEmpleado(); limpiarFormularioPeriodo(); limpiarFormularioPlanilla(); setFiltroEmpleados(""); }}>Inicio</a>
          <a href="#" onClick={() => { setVista("empleados"); limpiarFormularioPeriodo(); limpiarFormularioPlanilla(); }}>Empleados</a>
          <a href="#" onClick={() => { setVista("periodos"); limpiarFormularioEmpleado(); limpiarFormularioPlanilla(); }}>Períodos</a>
          <a href="#" onClick={() => { setVista("planillas"); limpiarFormularioEmpleado(); limpiarFormularioPeriodo(); }}>Planillas</a>
          <a href="#">Prestaciones</a>
          <a href="#">Ausencias</a>
        </nav>
        <div className="right-section">
          <div className="social-icons">
            <FaFacebookF />
            <FaInstagram />
            <FaYoutube />
          </div>
        </div>
      </header>

      {vista === "home" && renderHome()}
      {vista === "empleados" && renderEmpleados()}
      {vista === "periodos" && renderPeriodos()}
      {vista === "planillas" && renderPlanillas()}

      <footer className="footer">
        © 2026 Texaco El Salvador - Sistema de Control de Planillas
      </footer>
    </div>
  );
}
